      commonMistakes: {
        id: 'common-mistakes',
        title: 'Häufige Fehler',
        items: [
          '**Fehler 1: n8n auf einem Laptop ausführen, der schläft.** Geschlossener-Deckel-Schlaf pausiert Docker; geplante Workflows stoppen bis zum Öffnen des Laptops. Kalender-Hinweise kommen 6 Stunden zu spät an. Fix: einen Pi 5 (€120) oder Mac mini für den Always-on-Host verwenden. Oder Power-Einstellungen zu "nie schlafen, wenn an AC" ändern und den Laptop andocken.',
          '**Fehler 2: Ein 7B+-Modell auf 4 GB RAM verwenden.** Llama 3.3 8B oder Qwen3 7B auf einem Pi 5 8GB swapped zu Disk und braucht 30+ Sekunden pro E-Mail-Triage — nutzbar aber schmerzhaft. Fix: zu Llama 3.2 3B Q4_K_M für Triage/Summary auf 8 GB Geräten halten. Zu 7B nur auf 16 GB+-Hardware upgraden.',
          '**Fehler 3: Cloudflare Tunnel überspringen und Port 5678 direkt freigeben.** Ein öffentliches n8n im offenen Internet ist ein Credential-Harvesting-Magnet innerhalb von Stunden. Fix: n8n nie port-forwarder. Cloudflare Tunnel (kostenlos) gibt Ihnen einen einzigartigen Hostname mit eingebautem DDoS-Schutz. n8n-Basis-Auth-Passwort auf einen 24-Zeichen-Zufall sperren.',
          '**Fehler 4: Das LLM um freie Ausgabe bitten und mit Regex parsen.** Llama 3.2 3B gibt gelegentlich " Hier ist das JSON: ```json\\n{...}\\n``` " mit Prosa um das JSON zurück. Regex-Parsing schlägt etwa 5 % der Durchläufe fehl. Fix: Ollama-JSON-Modus verwenden (`format: "json"` im API-Aufruf), der Ausgabe auf gültiges JSON beschränkt. Drop Parse-Fehler auf etwa 0,1 %.',
          '**Fehler 5: Keine Benachrichtigung bei Ausfall.** Zapier e-mailt Sie, wenn eine Zap bricht; n8n bleibt still, wenn Sie keinen Error-Handler verdrahten. Fix: Globalen n8n-Fehler-Workflow hinzufügen, der Fehler von anderen Workflows erfasst und über ntfy oder Pushover benachrichtigt. 5-Minuten-Einrichtung, spart Stunden von "warum funktioniert meine Email-Triage seit einer Woche nicht?"',
        ],
      },
