      commonMistakes: {
        id: 'common-mistakes',
        title: 'Errores comunes',
        items: [
          '**Error 1: Ejecutar n8n en un portátil que entra en suspensión.** La suspensión al cerrar la tapa pausa Docker; los flujos programados dejan de ejecutarse hasta que abres el portátil. Los recordatorios de calendario llegan 6 horas tarde. Solución: usa una Pi 5 ($130) o un Mac mini como host siempre encendido. O cambia la configuración de energía a "nunca entrar en suspensión con CA" y mantén el portátil en el dock.',
          '**Error 2: Usar un modelo de 7B+ con 4 GB de RAM.** Llama 3.3 8B o Qwen3 7B en una Pi 5 8GB hace swap al disco y tarda 30+ segundos por triaje de correo — usable pero doloroso. Solución: usa Llama 3.2 3B Q4_K_M para triaje/resumen en dispositivos de 8 GB. Sube a 7B solo en hardware de 16 GB+.',
          '**Error 3: Saltarse el túnel de Cloudflare y exponer el puerto 5678 directamente.** Un n8n público en internet abierto es un imán de recolección de credenciales en cuestión de horas. Solución: nunca hagas port-forward de n8n. Cloudflare Tunnel (gratuito) te da un hostname único con protección DDoS integrada. Bloquea la contraseña de autenticación básica de n8n con una cadena aleatoria de 24 caracteres.',
          '**Error 4: Pedir al LLM salida de formato libre y parsear con regex.** Llama 3.2 3B devuelve ocasionalmente " Aquí está el JSON: ```json\\n{...}\\n``` " con prosa alrededor del JSON. El parseo con regex falla en ~5% de las ejecuciones. Solución: usa el modo JSON de Ollama (`format: "json"` en la llamada de API) que restringe la salida a JSON válido. Los fallos de parseo caen a ~0,1%.',
          '**Error 5: Sin alertas en caso de fallo.** Zapier te envía un correo cuando un Zap falla; n8n permanece en silencio a menos que conectes un manejador de errores. Solución: agrega un flujo de error global en n8n que capture los fallos de cualquier otro flujo y envíe una notificación a través de ntfy o Pushover. 5 minutos de configuración, ahorra horas de "¿por qué mi triaje de correo dejó de funcionar hace una semana?"',
        ],
      },
