          '**OAuth gerenciado** — o Zapier gerencia cada refresh de token, cada atualização de tela de consentimento, cada mudança de ToS de integração. Com o n8n, quando o Google rotaciona um escopo OAuth, você corrige.',
          '**7.000+ integrações pré-configuradas** — o n8n tem ~400. Se seu stack inclui um SaaS de nicho (por exemplo, um CRM regional, um HRIS específico), o Zapier quase certamente o tem; o n8n provavelmente não.',
          '**Webhooks públicos de imediato** — cada disparador "Catch Hook" do Zapier recebe automaticamente uma URL pública. O local precisa de Cloudflare Tunnel ou ngrok mais DNS.',
