            a: 'Não, planeje para ~80%. Os fluxos que dependem de integrações de SaaS de nicho que o Zapier suporta nativamente (por exemplo, CRMs regionais específicos, plataformas de folha de pagamento) são a lacuna. Os 5 fluxos deste guia são os casos de alto volume que o local gerencia corretamente. Para todo o resto, execute o nível gratuito do Zapier (100 tarefas/mês) junto com o n8n.',
