          '**n8n** (Apache 2.0, 자체 호스팅) — 워크플로우 엔진. ~400개의 사전 구성 통합(Gmail, Notion, Google Drive, RSS, HTTP, 스케줄링). 드래그 앤 드롭 빌더. 오픈소스 세계에서 Zapier의 UX에 가장 가까운 1:1 대체재.',
          '**Ollama** — 로컬 LLM 런타임. 한 줄 설치, `http://localhost:11434`에서 OpenAI 호환 API를 노출합니다. n8n은 HTTP Request 노드 또는 전용 Ollama 노드를 통해 이를 호출합니다.',
          '**Llama 3.2 3B Q4_K_M** — Meta의 30억 매개변수 모델로 4GB RAM에서 작동합니다. 이메일 분류, RSS 요약, 짧은 텍스트 생성에 충분히 강력합니다. Pi 5에서 충분히 빠릅니다 (약 5 토큰/초).',
